@Entity
class Product {
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;
    @Column(nullable = false)
    private String name;
    protected Product() {}
    Product(String name) { this.name = name; }
}

@Transactional
public void rename(long id, String name) {
    Product product = entityManager.find(Product.class, id);
    if (product == null) throw new IllegalArgumentException("상품 없음");
    product.rename(name);
    entityManager.flush();
    // 여기서 예외로 롤백되면 이름 변경도 확정되지 않는다.
}

